<x-capstone::dialog id="new-bid" title="Kirim Bid Baru" width="max-w-[520px]" description="Pilih judul untuk di-bid. Pembimbing ditetapkan saat finalisasi (penyeimbangan)."><p class="text-sm mt-2"><span class="font-medium" x-text="Math.max(0,3-total)+' slot tersisa'"></span> (max 3 bids + proposals combined).</p><form @submit.prevent="save()"><div class="grid gap-4 py-4"><x-capstone::alert variant="destructive" x-show="errors.root"><span x-text="errors.root"></span></x-capstone::alert><label class="grid gap-2 text-sm font-medium" for="bid-title">Judul <select id="bid-title" x-model="form.title_id" required class="border-input h-9 w-full rounded-md border bg-transparent px-3 text-sm"><option value="">Pilih judul...</option><template x-for="title in availableTitles" :key="title.id"><option :value="String(title.id)" x-text="title.title"></option></template></select></label>
</div><div class="flex justify-end gap-2"><x-capstone::button variant="outline" @click="close('new-bid')">Batal</x-capstone::button><x-capstone::button type="submit" ::disabled="saving || !canSubmit">Kirim Bid</x-capstone::button></div></form></x-capstone::dialog>
